"""Offline review browser; client text escaped, no external resources or uploads."""
import json,html
from pathlib import Path
import os
root=Path(os.environ.get('TK_PAIR_DIR','data/narrative-model/matter-pairs-2026-11-04'));rows=list(map(json.loads,(root/'all-pairs.jsonl').read_text().splitlines()));manifest=json.loads((root/'manifest.json').read_text());h=html.escape
parts=[]
for r in rows:
 matter=(r.get('matter') or {}).get('short_name','Unassigned');flags=', '.join(r['warnings']) or 'Candidate';context=r.get('context') or 'No matter context.'
 details='<details><summary>Prior context and source</summary><pre>'+h(context)+'</pre><p>Original finalized text: '+h(r['raw_target'])+'</p><p>Original saved shorthand: '+h(r.get('observed_brief') or 'None')+'</p><p>Generator shorthand: '+h(r.get('model_shorthand') or 'Fallback')+'</p><p>Explicitly retained facts: '+h(json.dumps(r['repairs'],ensure_ascii=False))+'</p></details>'
 parts.append('<tr data-ready="'+str(r['eligible_for_expansion_training']).lower()+'"><td>'+str(r['entry_id'])+'<br>'+r['date']+'<br>'+h(matter)+'<br><small>'+h(flags)+'</small></td><td>'+h(r['synthetic_shorthand'])+'</td><td>'+h(r['target'])+details+'</td></tr>')
page='''<!doctype html><meta charset="utf-8"><title>Matter-grounded shorthand pairs</title><style>body{font:15px system-ui;max-width:1600px;margin:32px auto;padding:16px;background:#faf9f5;color:#222}table{border-collapse:collapse;width:100%}th,td{padding:12px;border:1px solid #d5d1c9;text-align:left;vertical-align:top}td:first-child{width:17%}td:nth-child(2){width:28%}input{font:inherit;padding:10px;margin:10px 15px 20px 0}pre{white-space:pre-wrap;font:13px system-ui}small{color:#665b47}summary{cursor:pointer;margin-top:12px}</style><h1>Matter-grounded shorthand pairs</h1>'''
page+=f'<p>{manifest["source_finalized"]} finalized source entries; {manifest["eligible"]} unflagged expansion-training candidates; {manifest["observed_pairs"]} saved original briefs. Every source remains visible, including review-only cases. Targets come from finalized records, not generated expansions.</p><p>Open a row to inspect the dated context and any explicitly retained facts. All history is finalized work on the exact matter from earlier dates. Candidate checks are heuristic, not a guarantee of factual recoverability.</p>'
page+='''<input id="q" placeholder="Filter by matter, name, document or text" size="52"><label><input id="ready" type="checkbox">Unflagged candidates only</label><span id="count"></span><table><thead><tr><th>Source</th><th>Synthetic shorthand</th><th>Finalized narrative</th></tr></thead><tbody>'''+''.join(parts)+'''</tbody></table><script>const rows=[...document.querySelectorAll('tbody tr')];function filter(){const q=document.getElementById('q').value.toLowerCase(),ready=document.getElementById('ready').checked;let n=0;for(const r of rows){const show=(!ready||r.dataset.ready==='true')&&r.textContent.toLowerCase().includes(q);r.hidden=!show;if(show)n++;}document.getElementById('count').textContent=n+' shown';}document.getElementById('q').addEventListener('input',filter);document.getElementById('ready').addEventListener('change',filter);filter();</script>'''
(root/'pairs.html').write_text(page);print(root/'pairs.html')
